def transform(grid):
    def iso(c):
        pos=[(i,j) for i,r in enumerate(grid) for j,x in enumerate(r) if x==c]
        return all((i+di,j+dj) not in pos for i,j in pos for di,dj in ((1,0),(-1,0),(0,1),(0,-1)))
    return [[8 if (1<=3*i+j<=7 and any(x==3*i+j for r in grid for x in r) and iso(3*i+j)) else 0 for j in range(3)] for i in range(3)]
