import itertools
from collections import Counter
def bandsets():
    out=[]
    for sr in itertools.product([2,3],[2,3],[2,3]):
        if sum(sr)==7:
            R=[];s=0
            for z in sr: R.append(list(range(s,s+z))); s+=z
            out.append(R)
    return out
BS=bandsets()
preds={}
def mk(name,fn): preds[name]=fn
# predicate over block contents: count of cells satisfying sel
sels={
 'nonbg': lambda d,c,bg,w: lambda v: v!=bg,
 'notwall': lambda d,c,bg,w: lambda v: v not in (bg,w),
 'rare1': lambda d,c,bg,w: lambda v: c[v]<=1 and v!=bg,
 'rare2': lambda d,c,bg,w: lambda v: c[v]<=2 and v!=bg and v!=w,
 'rare2nw': lambda d,c,bg,w: lambda v: c[v]<=2 and v!=bg,
}
agg={'odd':lambda n:n%2==1,'even':lambda n:n%2==0,'nonzero':lambda n:n>0,'one':lambda n:n==1,'gt1':lambda n:n>1,'two':lambda n:n==2}
res=[]
for sname,smk in sels.items():
    for aname,afn in agg.items():
        for R in BS:
            for C in BS:
                ok=True
                for k,(d,o) in dems.items():
                    c=Counter(x for r in d for x in r); bg=c.most_common(1)[0][0]
                    ranked=[x for x,_ in c.most_common()]; w=ranked[1] if len(ranked)>1 else bg
                    sel=smk(d,c,bg,w)
                    pred=[[8 if afn(sum(1 for r in R[i] for cc in C[j] if sel(d[r][cc]))) else 0 for j in range(3)] for i in range(3)]
                    if pred!=o: ok=False; break
                if ok: res.append((sname,aname,R,C))
print(res[:10], len(res))

