    yield 'nebg', v!=bg
    yield 'new', v not in (bg,w)
    yield 'rare', 0<c[v]<=2
    yield 'odd', v%2==1
    yield 'gt4', v>4
for a in (1,2):
    for bi in range(0,7-3*a+1):
        for bj in range(0,7-3*a+1):
            for T in (False,True):
                for pn in ['eq8','ne0','nebg','new','rare','odd','gt4']:
                    ok=True
                    for k,(d,o) in dems.items():
                        c=Counter(x for r in d for x in r); bg=c.most_common(1)[0][0]
                        ranked=[x for x,_ in c.most_common()]; w=ranked[1] if len(ranked)>1 else bg
                        pred=[[0]*3 for _ in range(3)]
                        for i in range(3):
                            for j in range(3):
                                r,cc=(a*j+bj,a*i+bi) if T else (a*i+bi,a*j+bj)
                                for nm,val in preds(d[r][cc],c,bg,w):
                                    if nm==pn and val: pred[i][j]=8
                        if pred!=o: ok=False; break
                    if ok: res.append((a,bi,bj,T,pn))
