            f.update(minr=min(i for i,j in ps),maxr=max(i for i,j in ps),minc=min(j for i,j in ps),maxc=max(j for i,j in ps),
                     sums=sum(i+j for i,j in ps), sumr=sum(i for i,j in ps), sumc=sum(j for i,j in ps),
